 }

 function closeShareModal(){
 document.getElementById("shareModal").classList.remove("open");
 document.getElementById("shareModal").setAttribute("aria-hidden", "true");
 }

 function copyShareLink(){
 const input = document.getElementById("shareLinkInput");
 const copyBtn = document.getElementById("copyShareBtn");
 const resetLabel = function() { copyBtn.textContent = "Copy"; };
 const setCopied = function() {
 copyBtn.textContent = "Copied";
 setTimeout(resetLabel, 1200);
 };

 if (navigator.clipboard && navigator.clipboard.writeText) {
 navigator.clipboard.writeText(input.value).then(setCopied).catch(function(){
 input.select();
 document.execCommand("copy");
 setCopied();
 });
 return;
 }

 input.select();
 document.execCommand("copy");
 setCopied();
 }

